-- 7dc45544 | في أي عام كانت الهجرة النبوية إلى المدينة؟
UPDATE qa_questions SET
  answer = 'خرج النبي صلى الله عليه وسلم من مكة مهاجرًا في ليلة السابع والعشرين من صفر سنة أربع عشرة من النبوة، ودخل المدينة في ربيع الأول منها، الموافق سنة ٦٢٢م؛ فالهجرة وقعت بعد تمام ثلاث عشرة سنة من المبعث، لا في الثالثة عشرة منه، فإن الثلاث عشرة هي مدّة المكث بمكة كلَّها: قال المباركفوري في تقسيم عهد الدعوة: «١- الدور المكي ، ثلاث عشرة سنة تقريبا. ٢- الدور المدني، عشر سنوات كاملة»، ثم حدَّد ليلة الخروج: «غادر رسول الله صلى الله عليه وسلم بيته في ليلة ٢٧ من شهر صفر سنة ١٤ من النبوة»، وليلة الرحيل من الغار: «فلما كانت ليلة الإثنين- غرة ربيع الأول سنة ١ هـ/ ١٦ سبتمبر سنة ٦٢٢ م-». وبمَقدَمه صلى الله عليه وسلم المدينةَ أرَّخ الصحابة، قال سهل بن سعد رضي الله عنه: «مَا عَدُّوا مِنْ مَبْعَثِ النَّبِيِّ ، وَلَا مِنْ وَفَاتِهِ، مَا عَدُّوا إِلَّا مِنْ مَقْدَمِهِ الْمَدِينَةَ»؛ وإنما كُتب هذا التاريخ ودُوِّن في خلافة عمر بن الخطاب رضي الله عنه، قال الذهبي: «أول من كتب التاريخ عمر بن الخطاب -رضي الله عنه- لسنتين ونصف من خلافته، فكتب لست عشرة من الهجرة بمشورة علي رضي الله عنه».',
  reference = 'الرحيق المختوم للمباركفوري (دار الفكر، طبعة خاصة بدار ومكتبة الهلال ببيروت، ٢٠٠٢م): ص٦٤ (أدوار الدعوة ومراحلها)، وص١٤٨ (من الدار إلى الغار)، وص١٥١ (في الطريق إلى المدينة)؛ صحيح البخاري (ط السلطانية): رقم ٣٩٣٤ (باب التاريخ من أين أرخوا التاريخ)؛ سير أعلام النبلاء للذهبي (ط الرسالة): مجلَّد سيرة الخلفاء الراشدين، ص١١٩ (سيرة عمر الفاروق)',
  evidence = 'قسَّم المباركفوري عهد الدعوة فقال: «١- الدور المكي ، ثلاث عشرة سنة تقريبا. ٢- الدور المدني، عشر سنوات كاملة» (ص٦٤)، ثم حدَّد ليلة الخروج من مكة: «غادر رسول الله صلى الله عليه وسلم بيته في ليلة ٢٧ من شهر صفر سنة ١٤ من النبوة الموافق ١٢/ ١٣ سبتمبر سنة ٦٢٢ م» (ص١٤٨)، وليلة الرحيل من الغار إلى المدينة: «فلما كانت ليلة الإثنين- غرة ربيع الأول سنة ١ هـ/ ١٦ سبتمبر سنة ٦٢٢ م- جاءهما عبد الله بن أريقط بالراحلتين» (ص١٥١). وأما جعلُ الهجرة مبتدأ التاريخ فمن صنيع الصحابة: روى البخاري في باب التاريخ من أين أرخوا التاريخ، عن سهل بن سعد رضي الله عنه قال: «مَا عَدُّوا مِنْ مَبْعَثِ النَّبِيِّ ، وَلَا مِنْ وَفَاتِهِ، مَا عَدُّوا إِلَّا مِنْ مَقْدَمِهِ الْمَدِينَةَ» (رقم ٣٩٣٤). وقال الذهبي في سيرة عمر الفاروق: «أول من كتب التاريخ عمر بن الخطاب -رضي الله عنه- لسنتين ونصف من خلافته، فكتب لست عشرة من الهجرة بمشورة علي رضي الله عنه» (مجلَّد سيرة الخلفاء الراشدين، ص١١٩).',
  verification_status = 'verified'
WHERE id = '7dc45544-87e3-4099-a55e-ab543de99689'
  AND reference = 'الرحيق المختوم'
  AND evidence = 'أجمع أهل السير على وقوع الهجرة بعد البعثة بثلاث عشرة سنة.'
  AND answer = 'كانت الهجرة النبوية من مكة إلى المدينة في السنة الثالثة عشرة من البعثة، واتُّخذت بداية للتقويم الهجري في عهد عمر بن الخطاب رضي الله عنه.';

-- 8205c923 | ما أعظم درس في الهجرة؟
UPDATE qa_questions SET
  answer = 'من أعظم دروسها التوكّل على الله مع استيفاء الأسباب، لا أحدهما دون الآخر: فقد بلغ النبي صلى الله عليه وسلم في الأخذ بالأسباب أقصاه — أنام عليًّا رضي الله عنه في فراشه وقال له: «نم على فراشي، وتسبح ببردي هذا الحضرمي الأخضر، فنم فيه، فإنه لن يخلص إليك شيء تكرهه منهم»، وخرج قبل الفجر من باب خلفي، «فقد سلك الطريق الذي يضاده تماما» لعلمه أن الأنظار تتجه إلى طريق المدينة الشمالي، واستأجر دليلًا مشركًا خِرِّيتًا ماهرًا بالطريق وأمَّنه، ومكث في الغار ثلاث ليال حتى خمدت نار الطلب — ثم لم يكن معقِده في ساعة العُسرة إلا الله، فلما رأى أبو بكر أقدام القوم على باب الغار قال له: «اسكت يا أبا بكر، اثنان الله ثالثهما»، ولما لحقهما سراقة قال: «لا تَحْزَنْ إِنَّ اللَّهَ مَعَنا»؛ وهو ما أنزل الله فيه: ﴿إِذْ يَقُولُ لِصَٰحِبِهِۦ لَا تَحْزَنْ إِنَّ ٱللَّهَ مَعَنَا ۖ فَأَنزَلَ ٱللَّهُ سَكِينَتَهُۥ عَلَيْهِ وَأَيَّدَهُۥ بِجُنُودٍۢ لَّمْ تَرَوْهَا﴾ [التوبة: ٤٠] — فجعل السكينة والتأييد جوابًا للتوكّل، لا بدلًا من العمل.',
  reference = 'القرآن الكريم: التوبة ٤٠؛ الرحيق المختوم للمباركفوري (دار الفكر، طبعة خاصة بدار ومكتبة الهلال ببيروت، ٢٠٠٢م): ص١٤٧ (الرسول صلى الله عليه وسلم يغادر بيته)، وص١٤٨ (من الدار إلى الغار)، وص١٥٠ وص١٥٣ (في الطريق إلى المدينة) | الكلمات المفتاحية: هجرة، سيرة، توكل',
  evidence = 'قال الله تعالى في شأن الهجرة: ﴿إِذْ أَخْرَجَهُ ٱلَّذِينَ كَفَرُوا۟ ثَانِىَ ٱثْنَيْنِ إِذْ هُمَا فِى ٱلْغَارِ إِذْ يَقُولُ لِصَٰحِبِهِۦ لَا تَحْزَنْ إِنَّ ٱللَّهَ مَعَنَا ۖ فَأَنزَلَ ٱللَّهُ سَكِينَتَهُۥ عَلَيْهِ وَأَيَّدَهُۥ بِجُنُودٍۢ لَّمْ تَرَوْهَا﴾ [التوبة: ٤٠]. واستوفى النبي صلى الله عليه وسلم الأسباب كلَّها مع هذا التوكّل، كما ساقها المباركفوري: أمر عليًّا رضي الله عنه فقال له: «نم على فراشي، وتسبح ببردي هذا الحضرمي الأخضر، فنم فيه، فإنه لن يخلص إليك شيء تكرهه منهم» (ص١٤٧)، «ولما كان النبي صلى الله عليه وسلم يعلم أن قريشا ستجد في الطلب، وأن الطريق الذي ستتجه إليه الأنظار لأول وهلة هو طريق المدينة الرئيسي المتجه شمالا، فقد سلك الطريق الذي يضاده تماما» (ص١٤٨)، «وكانا قد استأجر عبد الله بن أريقط الليثي، وكان هاديا خريتا- ماهرا بالطريق- وكان على دين كفار قريش، وأمناه على ذلك» (ص١٥٠). ثم لما بلغ الطلبُ بابَ الغار كان مَعقِده التوكّل وحده: «روى البخاري عن أنس عن أبي بكر قال: كنت مع النبي صلى الله عليه وسلم في الغار فرفعت رأسي، فإذا أنا بأقدام القوم، فقلت يا نبي الله لو أن بعضهم طأطأ بصره رآنا. قال: اسكت يا أبا بكر، اثنان الله ثالثهما» (ص١٥٠)، ولما لحقهما سراقة: «فقلت: هذا الطلب قد لحقنا يا رسول الله، فقال: لا تَحْزَنْ إِنَّ اللَّهَ مَعَنا» (ص١٥٣).',
  verification_status = 'verified'
WHERE id = '8205c923-9d20-49dd-af3c-fc4f4ca0a37d'
  AND reference = 'القرآن الكريم؛ الرحيق المختوم | الكلمات المفتاحية: هجرة، سيرة، توكل'
  AND evidence = 'قال تعالى: ﴿إِذْ يَقُولُ لِصَاحِبِهِ لَا تَحْزَنْ إِنَّ اللَّهَ مَعَنَا﴾ [التوبة: 40].'
  AND answer = 'من أعظم دروسها التوكل على الله مع الأخذ بالأسباب والثبات على الحق.';

-- 7d8a6cc6 | لماذا سُميت غزوة الأحزاب بهذا الاسم؟
UPDATE qa_questions SET
  answer = 'سُميت بذلك لأن أحزابًا من العرب واليهود تحزَّبت مجتمعةً على النبي صلى الله عليه وسلم لحصار المدينة، وهو نصُّ ابن إسحاق في نفَرٍ من يهود بني النضير وبني وائل قدِموا مكة يدعون قريشًا إلى حربه: «وَهُمْ الَّذِينَ حَزَّبُوا الْأَحْزَابَ عَلَى رَسُولِ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ»؛ فخرجت قريش وقائدها أبو سفيان بن حرب، وغطفان وقائدها عيينة بن حصن في بني فزارة، والحارث بن عوف المرّي في بني مرة، ومسعر بن رخيلة فيمن تابعه من أشجع. وبها سمّاهم القرآن ﴿جُنُودٌۭ﴾ في قوله: ﴿ٱذْكُرُوا۟ نِعْمَةَ ٱللَّهِ عَلَيْكُمْ إِذْ جَآءَتْكُمْ جُنُودٌۭ فَأَرْسَلْنَا عَلَيْهِمْ رِيحًۭا وَجُنُودًۭا لَّمْ تَرَوْهَا﴾ ﴿إِذْ جَآءُوكُم مِّن فَوْقِكُمْ وَمِنْ أَسْفَلَ مِنكُمْ﴾ [الأحزاب: ٩-١٠]. وتُسمَّى غزوة الخندق كذلك، وكانت «فِي شَوَّالٍ سَنَةَ خَمْسٍ»، لأن النبي صلى الله عليه وسلم «ضَرَبَ الْخَنْدَقَ عَلَى الْمَدِينَةِ، فَعَمِلَ فِيهِ ... تَرْغِيبًا لِلْمُسْلِمِينَ فِي الْأَجْرِ، وَعَمِلَ مَعَهُ الْمُسْلِمُونَ فِيهِ». وأما نسبةُ المشورة بحفره إلى سلمان الفارسي رضي الله عنه فقد ذكرها ابن هشام بصيغة التمريض لا بالجزم: «يُقَالُ: إنَّ سَلْمَانَ الْفَارِسِيَّ أَشَارَ بِهِ عَلَى رَسُولِ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ».',
  reference = 'القرآن الكريم: الأحزاب ٩-١٠؛ السيرة النبوية لابن هشام (ت السقا والأبياري والشلبي): ج٢/ص٢١٤ (تحريض اليهود لقريش)، وص٢١٥ (خروج الأحزاب من المشركين)، وص٢١٦ (حفر الخندق)، وص٢٢٤ (سلمان وإشارته بحفر الخندق) | الكلمات المفتاحية: غزوة الأحزاب، غزوة الخندق',
  evidence = 'قال الله تعالى: ﴿يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ ٱذْكُرُوا۟ نِعْمَةَ ٱللَّهِ عَلَيْكُمْ إِذْ جَآءَتْكُمْ جُنُودٌۭ فَأَرْسَلْنَا عَلَيْهِمْ رِيحًۭا وَجُنُودًۭا لَّمْ تَرَوْهَا﴾ ﴿إِذْ جَآءُوكُم مِّن فَوْقِكُمْ وَمِنْ أَسْفَلَ مِنكُمْ وَإِذْ زَاغَتِ ٱلْأَبْصَٰرُ وَبَلَغَتِ ٱلْقُلُوبُ ٱلْحَنَاجِرَ﴾ [الأحزاب: ٩-١٠]. وأصلُ التسمية في السيرة: قال ابن إسحاق في نفَرٍ من يهود بني النضير وبني وائل خرجوا إلى قريش يدعونهم إلى حرب النبي صلى الله عليه وسلم: «وَهُمْ الَّذِينَ حَزَّبُوا الْأَحْزَابَ عَلَى رَسُولِ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ» (ج٢/ص٢١٤)، ثم عدَّ الخارجين: «فَخَرَجَتْ قُرَيْشٌ، وَقَائِدُهَا أَبُو سُفْيَانَ بْنُ حَرْبٍ، وَخَرَجَتْ غَطَفَانُ، وَقَائِدُهَا عُيَيْنَةُ بْنُ حِصْنِ بْنِ حُذَيْفَةَ بْنِ بَدْرٍ» ... «وَالْحَارِثُ ابْن عَوْفِ بْنِ أَبِي حَارِثَةَ الْمُرِّيُّ، فِي بَنِي مُرَّةَ» (ج٢/ص٢١٥). وأما اسمُها الآخر فمن الخطّة الدفاعيّة: «ثُمَّ كَانَتْ غَزْوَةُ الْخَنْدَقِ فِي شَوَّالٍ سَنَةَ خَمْسٍ» (ج٢/ص٢١٤)، «ضَرَبَ الْخَنْدَقَ عَلَى الْمَدِينَةِ، فَعَمِلَ فِيهِ رَسُولُ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ تَرْغِيبًا لِلْمُسْلِمِينَ فِي الْأَجْرِ، وَعَمِلَ مَعَهُ الْمُسْلِمُونَ فِيهِ» (ج٢/ص٢١٦). ونسبةُ المشورة إلى سلمان ذكرها ابن هشام بصيغة التمريض: «قَالَ ابْنُ هِشَامٍ: يُقَالُ: إنَّ سَلْمَانَ الْفَارِسِيَّ أَشَارَ بِهِ عَلَى رَسُولِ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ» (ج٢/ص٢٢٤).',
  verification_status = 'verified'
WHERE id = '7d8a6cc6-492f-4a45-be25-57080f815cdf'
  AND reference = 'القرآن الكريم؛ السيرة النبوية | الكلمات المفتاحية: غزوة الأحزاب، غزوة الخندق'
  AND evidence = 'قال تعالى: ﴿إِذْ جَاءُوكُم مِّن فَوْقِكُمْ وَمِنْ أَسْفَلَ مِنكُمْ﴾ [الأحزاب: ١٠] يصف حصار الأحزاب للمدينة.'
  AND answer = 'سُميت بذلك لأن أحزابًا وقبائل عديدة (قريش وغطفان واليهود وغيرهم) تحالفت مجتمعة لحصار المدينة، ودافع عنها المسلمون بحفر الخندق حول المدينة بمشورة سلمان الفارسي.';

-- 58c7a2c0 | من هو أول من أسلم من الرجال الأحرار؟
UPDATE qa_questions SET
  answer = 'هو أبو بكر الصديق رضي الله عنه، وقيدُ الرجال الأحرار مقصودٌ لا زيادة: فترتيبُ السابقين عند ابن إسحاق في السيرة أن خديجة رضي الله عنها أوّلُ من آمن، ثم عليّ بن أبي طالب رضي الله عنه — «وكان صبيا يعيش في كفالة الرسول» — ثم زيد بن حارثة رضي الله عنه «مَوْلَى رَسُولِ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، وَكَانَ أَوَّلَ ذَكَرٍ أَسْلَمَ، وَصَلَّى بَعْدَ عَلِيِّ بْنِ أَبِي طَالِبٍ»، ثم قال: «ثُمَّ أَسْلَمَ أَبُو بَكْرِ بْنُ أَبِي قُحَافَةَ»؛ فأبو بكر أوّلُ من أسلم من الرجال الأحرار البالغين، لا أوّلُ الناس إسلامًا مطلقًا. وكان من خاصّته أنه «أَظْهَرَ إسْلَامَهُ، وَدَعَا إلَى اللَّهِ وَإِلَى رَسُولِهِ» من أوّل يومه، فأسلم بدعائه عثمان بن عفان والزبير وعبد الرحمن بن عوف وسعد بن أبي وقاص وطلحة بن عبيد الله رضي الله عنهم. وأما لقبُ «الصديق» فمن تصديقه النبيَّ صلى الله عليه وسلم في الإسراء — وهو متأخِّرٌ عن إسلامه بسنين، فليس دليلًا على سبقه — قال: «وَاَللَّهِ لَئِنْ كَانَ قَالَهُ لَقَدْ صَدَقَ»، فقال له النبي صلى الله عليه وسلم: «وَأَنْتَ يَا أَبَا بَكْرٍ الصِّدِّيقُ».',
  reference = 'السيرة النبوية لابن هشام (ت السقا والأبياري والشلبي): ج١/ص٢٤٧ (إسلام زيد بن حارثة)، وص٢٤٩-٢٥٠ (إسلام أبي بكر الصديق ومنزلته في قريش)، وج١/ص٣٩٩ (حديث عائشة عن مسراه صلى الله عليه وسلم)؛ الرحيق المختوم للمباركفوري (دار الفكر، طبعة خاصة بدار ومكتبة الهلال ببيروت، ٢٠٠٢م): ص٦٥ (الرعيل الأول)',
  evidence = 'ترتيبُ السابقين في السيرة: قال ابن إسحاق: «ثُمَّ أَسْلَمَ زَيْدُ بْنُ حَارِثَةَ» ... «مَوْلَى رَسُولِ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، وَكَانَ أَوَّلَ ذَكَرٍ أَسْلَمَ، وَصَلَّى بَعْدَ عَلِيِّ بْنِ أَبِي طَالِبٍ» (ج١/ص٢٤٧)، ثم قال: «ثُمَّ أَسْلَمَ أَبُو بَكْرِ بْنُ أَبِي قُحَافَةَ، وَاسْمُهُ عَتِيقٌ» (ج١/ص٢٤٩). وذكر المباركفوري السابقين الأوّلين بأوصافهم المميِّزة: «وفي مقدمتهم زوجة النبي صلى الله عليه وسلم أم المؤمنين خديجة بنت خويلد، ومولاه زيد بن حارثة بن شرحبيل الكلبي وابن عمه علي بن أبي طالب- وكان صبيا يعيش في كفالة الرسول- وصديقه الحميم أبو بكر الصديق» (ص٦٥). وأمرُ أبي بكر بعد إسلامه: «فَلَمَّا أَسْلَمَ أَبُو بَكْرٍ رَضِيَ اللَّهُ عَنْهُ: أَظْهَرَ إسْلَامَهُ، وَدَعَا إلَى اللَّهِ وَإِلَى رَسُولِهِ» (ج١/ص٢٤٩)، «فَجَعَلَ يَدْعُو إلَى اللَّهِ وَإِلَى الْإِسْلَامِ مَنْ وَثِقَ بِهِ مِنْ قَوْمِهِ» «فَأَسْلَمَ بِدُعَائِهِ- فِيمَا بَلَغَنِي- عُثْمَانُ بْنُ عَفَّانَ» (ج١/ص٢٥٠). وأما تصديقُه ليلة الإسراء فهو مستنَدُ لقبه لا مستنَدُ سَبْقِه، إذ الإسراء متأخِّرٌ عن إسلامه بسنين: «فَقَالَ أَبُو بَكْرٍ: وَاَللَّهِ لَئِنْ كَانَ قَالَهُ لَقَدْ صَدَقَ» ... «قَالَ رَسُولُ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ لِأَبِي بَكْرٍ: وَأَنْتَ يَا أَبَا بَكْرٍ الصِّدِّيقُ، فَيَوْمَئِذٍ سَمَّاهُ الصِّدِّيقَ» (ج١/ص٣٩٩، وهو مما رواه ابن إسحاق عن الحسن مرسلًا).',
  verification_status = 'verified'
WHERE id = '58c7a2c0-2a44-4101-a9f9-7d3a30cf7b9c'
  AND reference = 'سيرة ابن هشام'
  AND evidence = 'ثبت في السيرة سبقُه إلى الإسلام ومبادرته بتصديق النبي ﷺ ليلة الإسراء.'
  AND answer = 'أول من أسلم من الرجال الأحرار هو أبو بكر الصديق رضي الله عنه، وكان من أقرب الناس إلى النبي ﷺ وأكثرهم تصديقًا له.';
